export * from "./rota.js";

/** Options for a patrol. */
export interface PatrolOptions {
  /** How many officers walk the beat. Defaults to 2. */
  officers?: number;
  /** Walk the beat at night. Night patrols report over the clacks. */
  night?: boolean;
}

/** What a patrol found. */
export interface Report {
  beat: string;
  incidents: number;
  filedBy: string;
}

/**
 * Walk a beat and report what was found.
 *
 * @param beat The name of the beat, for example "Treacle Mine Road".
 * @param options Officers and time of day.
 * @returns The report, once the patrol is back at the Yard.
 */
export declare function patrol(beat: string, options?: PatrolOptions): Promise<Report>;

/**
 * Arrest a suspect and return the charge sheet number (WATCH-12 style).
 * @throws When the suspect is the Patrician.
 */
export declare function arrest(suspect: string, charge: string): string;

/** An officer of the Watch. */
export declare class Watchman {
  constructor(name: string, rank?: Rank);
  readonly name: string;
  /** Promote the officer one rank. Returns the new rank. */
  promote(): Rank;
}

export type Rank = "constable" | "corporal" | "sergeant" | "captain" | "commander";

export declare const VERSION: string;
